const TCF_VOCAB=TCF_DATA.map(([id,level,theme,f,ipa,z,source,ipaSource])=>({id,level,theme,f,ipa,z,source,ipaSource}));
const TCF_BY_ID=Object.fromEntries(TCF_VOCAB.map(x=>[x.id,x]));
const TCF_GROUPS={};
for(const level of ["A1","A2","B1","B2","C1"]){
  for(const theme of TCF_THEME_ORDER){
    const themeWords=TCF_VOCAB.filter(x=>x.level===level&&x.theme===theme);
    for(let i=0;i<themeWords.length;i+=25){
      const group=i/25+1,key=level+":"+theme+":"+group,chunk=themeWords.slice(i,i+25);
      TCF_GROUPS[key]={level,theme,group,count:chunk.length,ids:chunk.map(x=>x.id)};
    }
  }
}
// Keep Pêche's spelling-to-sound chunk layer for Learn/Review/Spelling.
// This rule-based chunking is a study aid; publisher IPA, when present, remains in x.ipa.
TCF_VOCAB.forEach(x=>{if(!x.pr&&typeof autoPron==="function")x.pr=autoPron(x.f)});
